        (state.cplNiceErr ? '<p class="err">' + esc(state.cplNiceErr) + "</p>" : "") +
        '<button type="button" class="btn block" data-action="cpl-nice-add">' + esc(CPL.niceSave) + "</button>" +
        '<p class="muted">' + esc(fill(CPL.niceLeft, { n: 3 - todayN })) + "</p>";
